setup:
CREATE TABLE inventory (
    sku text PRIMARY KEY,
    name text,
    qty integer
);
INSERT INTO inventory (sku, name, qty) VALUES
    ('A100', 'Desk lamp', 12),
    ('B200', 'Office chair', 5),
    ('C300', 'Notebook', 40),
    ('D400', 'Stapler', 8);
CREATE TABLE shipment (
    sku text,
    name text,
    qty integer
);
INSERT INTO shipment (sku, name, qty) VALUES
    ('B200', 'Office chair', 3),
    ('D400', 'Heavy stapler', 15),
    ('E500', 'Monitor stand', 6),
    ('F600', 'Desk mat', 20);

example.code:
-- Copy only the shipment rows whose sku is not in inventory yet
INSERT INTO inventory (sku, name, qty)
SELECT sku, name, qty
FROM shipment
WHERE sku NOT IN (SELECT sku FROM inventory);

SELECT * FROM inventory ORDER BY sku;

practice.solution:
CREATE TABLE big_items (
    sku text PRIMARY KEY,
    name text,
    qty integer
);

INSERT INTO big_items (sku, name, qty)
SELECT sku, name, qty
FROM shipment
WHERE qty > 10;

SELECT * FROM big_items ORDER BY sku;

