example.code:
-- New skus are inserted, existing skus get the shipment added on
INSERT INTO inventory (sku, name, qty)
SELECT sku, name, qty
FROM shipment
ON CONFLICT (sku) DO UPDATE SET qty = inventory.qty + EXCLUDED.qty;

SELECT * FROM inventory ORDER BY sku;

